import{_ as o,o as u,c as q,a0 as a}from"./chunks/framework.CSK6mTG2.js";const h=JSON.parse('{"title":"长上下文 vs RAG：什么时候该\\"塞全文\\"，什么时候该\\"查资料\\"","description":"","frontmatter":{"title":"长上下文 vs RAG：什么时候该\\"塞全文\\"，什么时候该\\"查资料\\"","author":"唐超","date":"2026-11-01T00:00:00.000Z"},"headers":[],"relativePath":"menuAI/long-context-vs-rag.md","filePath":"menuAI/long-context-vs-rag.md"}'),r={name:"menuAI/long-context-vs-rag.md"};function n(e,t,s,l,i,p){return u(),q("div",null,[...t[0]||(t[0]=[a('<h2 id="既然上下文窗口都-20-万-token-了-还要-rag-干嘛" tabindex="-1">&quot;既然上下文窗口都 20 万 token 了，还要 RAG 干嘛？&quot; <a class="header-anchor" href="#既然上下文窗口都-20-万-token-了-还要-rag-干嘛" aria-label="Permalink to &quot;&quot;既然上下文窗口都 20 万 token 了，还要 RAG 干嘛？&quot;&quot;">​</a></h2><p>这是最近一年被问得最多的问题。2023 年的时候，模型一次只能&quot;看&quot;几千字，你想让 AI 读一本手册，只能把相关的几页挑出来喂给它——这就是 RAG（检索增强生成）诞生的原因。现在呢？GPT-4 级、Claude、Kimi 这些动辄 20 万、甚至 100 万 token 的上下文窗口，差不多能把一整本书直接塞进去。</p><p>于是很多人想：得了，别搞什么向量数据库、什么召回重排了，直接把文档全丢进去不就完了？</p><p>这个问题问得特别好，但答案不是&quot;能塞就塞&quot;。今天我们就把这件事掰开揉碎讲清楚。</p><h2 id="先打个比方-抱本书-vs-带卡片盒" tabindex="-1">先打个比方：抱本书 vs 带卡片盒 <a class="header-anchor" href="#先打个比方-抱本书-vs-带卡片盒" aria-label="Permalink to &quot;先打个比方：抱本书 vs 带卡片盒&quot;">​</a></h2><p>想象两种工作状态：</p><ul><li><strong>长上下文模式</strong>：你怀里抱着一整本《公司制度汇编》（800 页），老板问你&quot;年假怎么算&quot;，你低头在怀里翻。</li><li><strong>RAG 模式</strong>：你桌上放着一个卡片盒，每张卡片只有一条制度的摘要。老板问年假，你先翻卡片盒找到&quot;年假&quot;那张，抽出对应的两三页，再回答。</li></ul><p>哪个快？哪个准？不一定。抱全书的人&quot;什么都知道&quot;，但翻起来累，而且书太厚了容易看花眼；带卡片盒的人只拿最相关的几页，干净利落，但前提是卡片盒里得有这条、而且你抽得对。</p><p>这就是长上下文和 RAG 的本质差别：<strong>一个靠&quot;全量在场&quot;，一个靠&quot;精准检索&quot;。</strong></p><h2 id="长上下文不是银弹-它有三个隐形代价" tabindex="-1">长上下文不是银弹：它有三个隐形代价 <a class="header-anchor" href="#长上下文不是银弹-它有三个隐形代价" aria-label="Permalink to &quot;长上下文不是银弹：它有三个隐形代价&quot;">​</a></h2><p>很多人以为&quot;窗口大 = 免费随便用&quot;，其实不是。长上下文有实打实的代价：</p><p><strong>第一，贵。</strong> 这是最实在的。模型处理每个 token 都要算注意力，而自注意力的开销是随长度平方级增长的（虽然有各种优化，但长就是贵）。你把 8 万 token 的全文塞进去，哪怕用户只问了一句&quot;总结第一段&quot;，这 8 万 token 每个都收钱、都占算力。RAG 只塞相关的 2000 token，成本差几十倍。</p><p><strong>第二，&quot;中间会丢&quot;。</strong> 研究里有个著名现象叫 &quot;lost in the middle&quot;（迷失在中间）：模型对放在一长段文本<strong>开头和结尾</strong>的信息记得最牢，对<strong>中间</strong>的内容最容易忽略。你塞得越多，关键信息越可能埋在模型&quot;走神&quot;的那一段。这就像你让同事读 50 页材料后回答问题，他往往只清晰记得第一页和最后一页写了啥。</p><p><strong>第三，噪声干扰 + 不溯源。</strong> 全文塞进去，里面无关的内容、过时的内容、甚至自相矛盾的内容都在场，模型可能被带偏。而且它&quot;看过的&quot;是一锅粥，你很难问它&quot;你这句结论出自第几页&quot;——RAG 因为只抽了具体片段，天生能告诉你出处。</p><p>（可以画一张图：左边一个大框&quot;上下文窗口 20 万 token&quot;，里面密密麻麻一堆字，中间标红&quot;信息易迷失区&quot;；右边是 RAG 管道&quot;检索→只取 3 段→生成&quot;，干净清爽。）</p><h2 id="rag-也不是万能-它的痛点在-检索这一步" tabindex="-1">RAG 也不是万能：它的痛点在&quot;检索这一步&quot; <a class="header-anchor" href="#rag-也不是万能-它的痛点在-检索这一步" aria-label="Permalink to &quot;RAG 也不是万能：它的痛点在&quot;检索这一步&quot;&quot;">​</a></h2><p>说 RAG 好，也得承认它的命门在&quot;检索准不准&quot;：</p><ul><li>如果你的卡片盒（知识库）建得烂——切分不合理、embedding 模型不行、没做重排——那抽出来的就是错的页，模型再聪明也答不对。这就是常说的&quot;垃圾进垃圾出&quot;。</li><li>RAG 是&quot;先检索再回答&quot;，如果用户的问题需要<strong>跨多份文档综合推理</strong>（比如&quot;对比 A 方案和 B 方案在三个文档里的说法&quot;），单次检索可能抽不全，得多次召回或配合 Agent 循环。</li><li>它依赖你提前把知识&quot;入库&quot;。知识没进去，它就不知道。</li></ul><p>所以正确的问题不是&quot;二选一&quot;，而是&quot;<strong>我的场景下，谁的主场？</strong>&quot;</p><h2 id="一个帮你做决定的-四问清单" tabindex="-1">一个帮你做决定的&quot;四问清单&quot; <a class="header-anchor" href="#一个帮你做决定的-四问清单" aria-label="Permalink to &quot;一个帮你做决定的&quot;四问清单&quot;&quot;">​</a></h2><p>下次纠结时，问自己这四个问题：</p><ol><li><strong>知识更新频繁吗？</strong> 如果你的内容天天变（比如实时库存、今天的股价），长上下文每次都得重新塞最新的，麻烦且易过期；RAG 只要更新那几条卡片就行。→ 偏向 RAG。</li><li><strong>需要溯源/引用吗？</strong> 法律、医疗、客服这类&quot;你得给我出处&quot;的场景，RAG 天生能附引用。→ 偏向 RAG。</li><li><strong>是真的需要&quot;通读全书&quot;吗？</strong> 比如&quot;通读这份 100 页合同，找出所有对甲方不利的条款&quot;——这种任务就是要全量扫描、不能漏，检索反而可能漏掉。→ 偏向长上下文（或&quot;长上下文 + RAG 召回关键段后再精读&quot;）。</li><li><strong>成本和延迟敏感吗？</strong> 高并发、每分钱都要算的场景，长上下文的算力账单会很难看。→ 偏向 RAG。</li></ol><h2 id="现实里-高手都用-混合拳" tabindex="-1">现实里，高手都用&quot;混合拳&quot; <a class="header-anchor" href="#现实里-高手都用-混合拳" aria-label="Permalink to &quot;现实里，高手都用&quot;混合拳&quot;&quot;">​</a></h2><p>别被&quot;二选一&quot;困住。真正好用的系统，往往是<strong>RAG 打头、长上下文收尾</strong>：</p><p>先用 RAG 从海量知识里精准召回最相关的几段（控制成本和噪声），再把这几段连同用户问题，喂给一个上下文窗口够大的模型做&quot;精读和综合&quot;。该省的钱省了，该看的细节也没漏。</p><p>再进阶一点：用 RAG 召回几十段做&quot;粗筛&quot;，再让模型在长上下文里对这几段做深度推理。检索负责&quot;别漏&quot;，长上下文负责&quot;想透&quot;。</p><p>（画个漏斗图：海量文档 → RAG 召回 Top-K → 长上下文精读 → 答案。上半段窄进，下半段深想。）</p><h2 id="给你一句人话总结" tabindex="-1">给你一句人话总结 <a class="header-anchor" href="#给你一句人话总结" aria-label="Permalink to &quot;给你一句人话总结&quot;">​</a></h2><ul><li><strong>RAG 是&quot;怕你看太多看花眼，所以只给你看该看的&quot;</strong>——省成本、能溯源、好更新，但前提是检索得准。</li><li><strong>长上下文是&quot;索性全摊开，你自己翻&quot;</strong>——适合必须通读、要综合推理的任务，但贵、且中间易丢。</li></ul><p>所以&quot;有了大窗口还要不要 RAG&quot;？答案是：<strong>要，而且更要用对地方。</strong> 大窗口解放的是&quot;精读&quot;这一步，而不是&quot;检索&quot;这一步。检索解决的是&quot;从海量里找对料&quot;，这事模型再聪明也替代不了——因为它总得先知道去哪找。</p><p>下次你设计 AI 功能，别一上来就&quot;全塞进去&quot;。先想清楚：这段信息，是该&quot;抱在怀里&quot;，还是该&quot;放在卡片盒里按需抽&quot;？</p>',31)])])}const d=o(r,[["render",n]]);export{h as __pageData,d as default};
